-- ===== Fusion des doublons =====
-- Recettes en double d'une recette ci-dessus (ancienne version, autre titre).
-- Les favoris et le planning sont reportés sur la bonne recette, puis le
-- doublon est supprimé. Sans effet sur une base neuve.
DO $$
DECLARE
  pair RECORD;
BEGIN
  FOR pair IN
    SELECT o.id AS old_id, n.id AS new_id
    FROM (VALUES
      ('Pâtes à la Carbonara', 'Spaghetti carbonara'),
      ('Salade Niçoise', 'Salade niçoise'),
      ('Soupe à l''Oignon', 'Soupe à l''oignon gratinée'),
      ('Granola Maison au Four', 'Granola maison'),
      ('Pain Perdu', 'Pain perdu'),
      ('Pancakes Moelleux', 'Pancakes'),
      ('Œufs Brouillés Ciboulette', 'Œufs brouillés'),
      ('Toast Avocat & Œuf Poché', 'Tartine avocat et œuf'),
      ('Porridge Avoine & Fruits Rouges', 'Porridge aux flocons d''avoine'),
      ('Compote de Pommes Maison', 'Compote de pommes'),
      ('Brownie Chocolat', 'Brownies'),
      ('Lasagnes Bolognaise', 'Lasagnes bolognaise'),
      ('Soupe Miso', 'Soupe miso')
    ) AS m(old_title, new_title)
    JOIN recipes n ON n.title = m.new_title AND n.created_by IS NULL
    JOIN recipes o ON o.title = m.old_title AND o.created_by IS NULL AND o.id <> n.id
  LOOP
    DELETE FROM favorite_recipes f
    WHERE f.recipe_id = pair.old_id
      AND EXISTS (SELECT 1 FROM favorite_recipes f2 WHERE f2.user_id = f.user_id AND f2.recipe_id = pair.new_id);

    UPDATE favorite_recipes SET recipe_id = pair.new_id WHERE recipe_id = pair.old_id;
    UPDATE planned_meals SET recipe_id = pair.new_id WHERE recipe_id = pair.old_id;

    DELETE FROM recipe_ingredients WHERE recipe_id = pair.old_id;
    DELETE FROM recipes WHERE id = pair.old_id;
  END LOOP;
END $$;


-- ===== Catalogue d'ingrédients : retire ceux qui ne servent plus =====
DELETE FROM ingredients i
WHERE NOT EXISTS (SELECT 1 FROM recipe_ingredients ri WHERE ri.ingredient_id = i.id);
